    "k": "Dörrinformationen beskriver en person som hittas livlös; uppgiften är att utföra basal HLR och agera enligt rutin. Tid: 6 minuter (enligt dörrinformation).",
    "d": "Livlös, inte normalt andande person = misstänkt hjärtstopp tills motsatsen bevisats. Kvaliteten (andel godkända kompressioner/inblåsningar och frekvens) är det som väger tyngst i mallen: 7 av 10 poäng.",
    "b": "Basal HLR 30:2 tills defibrillator/avancerat team övertar; AED så fort den finns. Allmän rekommendation: följ aktuella riktlinjer från Svenska rådet för hjärt-lungräddning – kontrollera att du känner till den senaste versionen.",
    "m": "Larma – även om rummet verkar tomt. Hålla luftvägen öppen under hela andningskontrollen (1,5 p). Rätt frekvens 100–120/min – räkna eller sjung rytmen i huvudet. Livshotande tillstånd – fel eller fördröjning påverkar överlevnad."
