    "fam": "Prostatapalpation",
    "exam": "Teknisk korrekt prostatapalpation på modell, tolkning av fynd och initierad utredning. 8 förekomster i 8 tillfällen, nästan uteslutande i omtentor (7 av 8).",
    "task": "Dörrinformationen anger att prostata ska undersökas på patientmodell (tid cirka 4 minuter nämns i en dörrinformation) och att fynd ska tolkas. Tid enligt respektive dörrinfo.",
    "prep": [
     "Öva handskar, glidmedel, stegvis information till patienten innan palpation.",
     "Lär dig typiska fynd: normal (mjuk, elastisk, avgränsad), BPH (förstorad, slät), cancer (hård, oregelbunden, fixerad – T3).",
     "Förbered utredning: PSA, MR/biopsi, metastasutredning."
    ],
    "steps": [
     "Presentera dig, förklara undersökningen och be om samtycke; hygien och handskar.",
     "Inspektera analregionen; för in fingret försiktigt.",
     "Palpera båda lober, sulcus och apex/bas.",
     "Beskriv fyndet högt (storlek, konsistens, begränsning, ömhet).",
     "Tolka och föreslå fortsatt utredning; förklara varför för patienten."
    ],
    "say": [
     "\"Jag kommer nu att undersöka prostatan; det kan kännas obehagligt men ska inte göra ont.\"",
     "\"Prostatan känns hård, oregelbunden och fixerad – misstänkt avancerad prostatacancer. Jag vill ta PSA och planera biopsi och metastasutredning.\""
    ],
    "interp": [
     "Hård, oregelbunden, fixerad prostata = misstanke om lokalt avancerad cancer (T3-fynd)."
    ],
    "ddx": [
     "BPH, prostatit, prostatacancer."
    ],
    "mgmt": [
     "PSA och andra blodprover, MR prostata, biopsi, metastasutredning vid hög misstanke; urologkontakt."
    ],
    "pitDoc": [
     "Dokumenterat: 6 av 10 p gäller tolkning och handläggning, inte själva tekniken."
    ],
    "pitGen": [
     "Allmänt: att glömma samtycke/information; att beskriva fyndet först efter undersökningen."
    ],
    "never": [
     "Båda lober.",
     "Uttala fyndet och misstanken.",
     "Förklara för patienten varför utredning."
    ],
