     "Inspektion i sittande och liggande.",
     "Bimanuell palpation, palpera även mot thoraxvägg.",
     "Undersök hela bröstet, båda sidor, samt lymfkörtlar (axill, supra- och infraklavikulärt).",
     "Hitta resistensen och beskriv den.",
     "Sammanfatta fynd och plan; skriv korrekt mammografiremiss."
