     "text": "Du är vikarierande underläkare på en reumatologisk klinik och träffar en 45-årig patient med misstänkt inflammatorisk ryggsjukdom.\nProver tagna inför besöket är normala, förutom lätt förhöjt P-CRP på 3.3 mg/L (referens <3 mg/L).\nDu har redan genomfört undersökning/status av patienten och hittar inget anmärkningsvärt, förutom ömhet kring övergången mellan ländrygg och bäcken vid flexion i ländrygg och höfter.\nDin uppgift är nu att:\n• Ta en adekvat anamnes utifrån misstanken om inflammatorisk ryggsjukdom\n• Skriva en remiss för en relevant radiologisk undersökning\nDu ska inte utföra någon kroppsundersökning.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
