     "text": "Det är måndag morgon och du ska ronda med sköterskan på vårdavdelningen.\nUnder helgen har flera nya patienter skrivits in på avdelningen. På jourrapporten hörde du om Maria, 48 år som just påbörjat adjuvant cytostatikabehandling med anledning av en koloncancer som opererades nyligen. Maria skrevs in igår kväll på grund av biverkningar efter den första cytostatikakuren.\nDu har nu sittrond på expeditionen med avdelningssköterskan som har ansvar för Maria.\nDin uppgift är nu att:\n1. Kommunicera med sköterskan och efterfråga information du behöver för att kunna bedöma situationen\n2. Ordinera de läkemedel som du bedömer är indicerade redan nu\n3. Besluta om eventuella övriga åtgärder\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
