     "text": "Du är läkare på en hälsocentral. Du träffar en 35-årig patient. Hen är inbokad för ett besök till dig då hen har känt sig trött och törstig sedan ett par månader.\nBlodprover tagna fastande inför besöket (referensområden inom parentes):\nHb 165 g/L (134-170)\nNatrium 139 mmol/L (137-145)\nGlukos 9,2 mmol/L (<6,1)\nKalium 3,8 mmol/L (3,5-4,4)\nSR 7 mm (<13)\nCO2 tot 26 mmol/L (23-32)\nC-peptid 0,19 nmol/L (0,37-1,47) Kreatinin 105 µmol/L (60-105)\nHbA1c 82 mmol/mol (<48)\nDin uppgift är att:\n1. Komplettera anamnesen!\n2. Informera patienten om sannolik diagnos och handläggning!\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
