     "text": "Patienten söker pga smärta i handen. Du får intrycket av att det kan röra sig om tumbasartros.\nDu får komplettera anamnes efter behov (denna bedöms EJ)\n• Undersök handen utifrån detta inkl tänkbara differentialdiagnoser!\n• Informera patienten om diagnosen tumbasartros! Du behöver inte diskutera behandling.\n• Planera EN utredande åtgärd och förklara denna för patienten!\nDu behöver inte redogöra för bedömaren, men förklara dina fynd och din bedömning för patienten!\nDu behöver INTE föreslå behandling!\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
