     "text": "Du vikarierar på en hälsocentral och träffar där en 44- årig kvinna som söker för smärta i nacken, höger skuldra.\nHon började känna av smärtan för cirka ett halvår sedan, från början någon gång ibland men under senaste tiden dagligen. Hon har tagit Alvedon sporadiskt men tycker inte att det hjälper.\nHar varit hemma med egen sjukskrivning när smärtan varit som värst.\nInför besöket lab Hb 132, SR 5,\nDin uppgift är att:\n1) Ta en strukturerad smärtanamnes\n2) Värdera anamnesen för att bilda dig en uppfattning om smärtkategori\n3) Ge minst ett förslag på behandling.\nDu behöver inte gå vidare med undersökning/status.\nPatienten på stationen är en figurant.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
