     "text": "Du är läkare på en hälsocentral och din nästa patient är Jordan som är 42 år gammal. Patienten har haft utslag i ansiktet som kommit och gått sedan några år tillbaka men aldrig så här illa. Det hettar och blir inte bättre av något hon har provat. Hon vill inte visa sig ute när hon ser ut som hon gör och vill ha hjälp.\nDin uppgift nu är att:\n- Ta en riktad anamnes\n- Beskriv vad du ser på bilderna\n- Ställ preliminär diagnos och informera patienten\n- Ge förslag på behandling/handläggning\n- Svara på patientens frågor\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
