     "text": "Du är underläkare på reumatologmottagningen och träffar på nybesök en tidigare frisk patient med nydebuterad reumatiod artrit.\nUnder konsultationen och vid klinisk undersökning framkommer att patienten har måttlig värk och stelhet i händer och fötter sedan två månader, och du hittar artriter i tre MCP-leder, två PIP-leder och tre\nMTP-leder. Patienten har inga allmänsymptom, utan tycker sig må bra. Inga avvikelser i blodprover förutom lätt inflammation och påvisbara RF (reumatiod faktor) och anti-CCP (antikroppar mot citrullinerad peptid).\nDin uppgift är nu att\n- Informera om diagnosen och besvara eventuella frågor.\n- Komplettera anamnesen med uppgifter av vikt för behandling av reumatoid artrit.\n- Föreslå antireumatisk behandling med lämplig disease modifying anti-rheumatic drugs (DMARD).\n- Informera om behandlingen och besvara patientens frågor.\nStatus förutom artiterna är normalt och patienten behöver ej undersökas.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
