     "text": "Du är läkare på en palliativ avdelning. Du blir kontaktad av en sjuksköterska på avdelningen på grund av ett förväntat dödsfall.\nVårdpersonal på avdelningen har noterat att en 74 årig cancersjuk man,\nWolfgang af Moribus, 19480101–0101, har slutat andas och ej längre är kontaktbar.\nDin uppgift är att:\n Konstatera dödsfallet utifrån indirekta kriterier.\n Diktera en journalanteckning gällande dödsfallet i patientens journal.\nBerätta hela tiden för bedömaren vad du gör!\nDiktafonen är en attrapp och det spelas inte in på riktigt.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in samt ut.",
     "file": "om-OSCE II HT22 Dörrinformation.pdf",
