    "date": "2023-06-01",
    "year": 2023,
    "type": "Ordinarie",
    "term": "VT",
    "spec": "Reumatologi",
    "family": "Reumatologi",
    "topic": "PMR",
    "title": "Ny polymyalgia reumatica",
    "comp": [
     "ANAM",
     "KOMM",
     "ORD"
    ],
    "source": "OSCE II VT23 Bedömningsunderlag.pdf",
    "page": 4,
    "door": {
     "text": "Du är AT-läkare på en hälsocentral och träffar för första gången en pigg och vital 80-årig patient som nyligen insjuknat i polymyalgia reumatika (PMR). Under konsultationen framkommer att patienten har tilltagande värk och stelhet i axlar, höfter och sätesmuskulatur sedan en månad. Du hittar vid klinisk undersökning stelhet och ömhet vid rörelser i axlar och höftleder, samt ömhet över trokanter major och tuber ischiadicum.\nI blodprover tagna inför besöket noterar du inflammation med SR 48 och CRP 39, men övriga prover är utan anmärkning. Patienten tycker sig förutom värken och stelheten må bra, och du misstänker ingen annan sjukdom än PMR.\nDin uppgift är nu att:\n- Informera om diagnosen och besvara eventuella frågor.\n- Komplettera anamnesen med uppgifter av vikt vid PMR och läkemedelsbehandling av PMR\n- Föreslå lämplig behandling.\n- Informera om behandlingen och besvara patientens frågor.\nStatus förutom värk och stelhet är normalt och patienten behöver ej undersökas.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
     "file": "OSCE II VT23 Dörrinformation.pdf",
     "page": 5
    },
    "rubric": {
     "tier": "auto",
     "total": 10,
     "items": [
      {
       "t": "Empatiskt förhållningssätt",
       "max": 1,
       "opts": [
        1,
        0.5,
        0
       ],
       "safety": false
      },
      {
       "t": "Frågar om diabetes eller nedsatt glukosintolerans, sömnstörning eller psykisk sjukdom, samt om osteoporos eller tidigare fraktur (2 områden ger full poäng)",
       "max": 2,
       "opts": [
        2,
        1,
        0
       ],
       "safety": false
      },
      {
       "t": "Frågar om symptom på temporalisarterit (ögonsymtom, huvudvärk, tuggclaudcatio, ömhet i hårbotten), (minst 2 symtom för full poäng)",
       "max": 2,
       "opts": [
        2,
        1,
        0
       ],
       "safety": false
      },
      {
       "t": "Ger aktivt patienten chans att ställa frågor",
       "max": 1,
       "opts": [
        1,
        0.5,
        0
       ],
       "safety": false
      },
      {
       "t": "Förklarar vad PMR är, medicinskt korrekt och begripligt",
       "max": 2,
       "opts": [
        2,
        1,
        0
       ],
       "safety": false
      },
      {
       "t": "Föreslår prednisolon 12,5-25 mg",
       "max": 1,
       "opts": [
        1,
        0.5,
        0
       ],
       "safety": false
      },
      {
       "t": "Anger korrekt tid (någon-några dagar) till behandlingssvar",
       "max": 1,
       "opts": [
        1,
        0.5,
        0
       ],
       "safety": false
      }
     ]
    },
    "guide": "reuma"
