     "text": "Du är på en allmänläkarmottagning och skall undersöka prostata per rektum på en vuxen man som söker för vattenkastningsbesvär. I examinationen använder vi en prostatapalpations-attrapp (torso). Du ska alltså genomföra en prostatapalpation som om det vore på en riktig patient. Du är helt klar med patientidentifikation och övrigt status som inte ska upprepas.\nDin uppgift är nu att:\n- undersöka prostata på patientmodellen (Du har cirka 4 minuter på dig för undersökningen och du meddelas när ungefär 2 minuter gått.)\n- ställa minst tre viktiga nyckelfrågor till patienten, som är direkt relevanta för den aktuella diagnostiska processen.\n- redogöra för vidare handläggning utifrån palpationsfynd.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
