    "door": {
     "text": "Du arbetar som underläkare på Ålidhems hälsocentral och är idag på\nBVC. Charlie är ett år gammal och kommer med sin ena förälder.\nCharlie har besvärats av klåda sedan några månader tillbaka och dessutom har det börjat dyka upp utslag på en del ställen på kroppen.\nCharlies föräldrar är oroliga och vill ha hjälp då de inte får sova på nätterna eftersom barnet är motoriskt orolig och gråter.\nDin uppgift är att:\n- ta anamnes,\n- beskriva vad du ser och\n- informera föräldrarna om diagnosen och handläggning.\nDu ska inte undersöka patienten!\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
     "file": "Dörrinformation OM OSCE II VT23.pdf",
     "page": 13
    },
