     "text": "Du är underläkare på en reumatologklinik. Du träffar en 35-årig patient med nydiagnostiserad reumatoid artrit (RA).\nDin uppgift är att:\n• Utföra ett ledstatus av handled och av mcp- och pip-leder i syfte att identifiera artriter.\n• Relatera undersökningen till typiska statusfynd vid inflammation.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
