     "text": "Du har träffat Sture 67 år på akutmottagningen. Han har lungcancer med spridning till lunga och lever och behandlas med cytostatika i kombination med immunterapi i första linjen. Utvärdering efter två kurer visar mycket god respons. Han söker nu med ett knappt dygns anamnes på feber, hosta och andfåddhet, tio dagar efter sin fjärde kur.\nProver visar Hb 82, LPK 0,7, TPK 123, CRP 22. Vätske- och lever/gallstatus är normala.\nI status noterar du rassel basalt bilateralt vid lungauskultation och BT 110/60 mmHg. Du noterar även Saturation 92% (luft) och Temp 39,2°C.\nYtterligare provtagning är ej genomförd. Du konstaterar febril neutropeni och bestämmer dig för att lägga in Sture på avdelningen.\nDin uppgift är att:\n• Rapportera patienten till sjuksköterskan på avdelningen.\n• Ordinera åtgärder/behandlingar för det kommande dygnet.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
