     "text": "Du är läkare på en hälsocentral. Patienten är 63 år. Hen är tidigare frisk, förutom några ÖLI-diagnoser, och har inga allergier eller läkemedel. Som kontaktorsak i bokningen anges blodtryck.\nBlodtryck 125/70 är taget idag i blodtrycksrummet. Inför besöket har även prover och EKG tagits. Svaren finns som bordsinformation i rummet.\nDu ska genomföra en\n• patientcentrerad konsultation och komma fram till\n• bedömning, ev åtgärd och planering.\nStatus ingår INTE i uppgiften\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
