     "text": "Du arbetar som narkosläkare på postoperativa avdelningen. En tidigare frisk 55 årig patient har blivit opererad med total höftplastik på grund av artros.\nOperationen genomfördes under ryggmärgsbedövning (spinalanestesi) och nu har bedövningen släppt helt. Patienten klagar över svåra smärtor i höften (VAS 8/10) och mår illa.\nSjuksköterskan, som jobbar på postoperativa avdelningen, frågar dig en plan för smärtbehandling för kommande dygnet.\nRedovisa din behandlingsplan muntligt och skriftligt för sjuksköterskan.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
