     "text": "Du vikarierar på en hälsocentral, nästa patient på din mottagning är Inger 43 år som söker pga. smärta i nacken, höger skuldra.\nHon började känna av smärtan för drygt ett halvår sedan, smärtan har därefter succesivt tilltagit. Inger har varit hemma ibland med egen sjukskrivning när smärtan varit som värst.\nHon vill nu ha hjälp med att få utredning och behandling.\nDu ska ta en strukturerad smärtanamnes samt ge minst ett förslag på behandling.\nDu behöver inte gå vidare med undersökning/status.\nDe färdigheter som ska bedömas är ditt möte med patienten, anamnes, förslag på handläggning/behandling av patient med långvarig smärta.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
