     "text": "Du är avdelningsläkare på en ortopedavdelning. Under gårdagen flyttades en traumapatient från den akutkirurgiska avdelningen till ortopedavdelningen.\nPatienten är tidigare frisk, 24 år gammal. Hon har kört omkull med sin motorcykel och handlades initialt på akutrummet enligt ATLS. Man har inte funnit några skador vid primär undersökning och 24 h observation.\nPatienten har flyttats till ortopedavdelning. På morgonens rond har hon ett ont och svullet höger knä. CT av höger knä har inte visat på några skelettskador.\nVid ronden ska du nu göra ett knästatus där du undersöker om det föreligger hydrops och utföra stabilitetstester av knät.\nUtifrån dina undersökningsfynd informera patienten hur du planerar vidare utredning.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
