     "text": "Kim, 25 år, söker på Hud- och STD-mottagningen på grund av intensivt kliande utslag på kroppen som kommer och går sedan 8 veckor. Kim känner sig orolig och vill veta vad denne har för sjukdom. Eftersom det inte finns utslag på huden just nu har Kim med sig bilder.\nDu ska:\n• Ta en adekvat anamnes\n• Informera patienten om utredning, diagnos och fortsatt handläggning\n• Besvara patientens frågor\nDu ska ej undersöka patienten!\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
