     "text": "Du har underläkarvikariat på röntgen. Kirurgjouren kommer till röntgenavdelningen och vill att du ska visa en akut DT buk på en patient.\nBilderna visas i IDS7 i tre snittplan med relevant fönstersättning. I röntgenremissen står följande:\nFrågeställning:\nHydronefros? Aneurysm? Dissektion? Ileus?\nKliniska upplysningar:\nIcke rökare.\nTidigare op. åderbråck på underben bilat. I övrigt frisk.\nTre veckors förkylning, fortfarande lite hosta.\nIngen feber i morse. Har tagit Alvedon.\nUppger sedan igår smärta till vänster i buken. Buksmärtan blir värre vid rörelse.\nLab:\nCRP 65. Krea 65. Längd 165 cm, vikt 65 kg\nDenna information finns även inne i rummet bredvid datorn.\nDu kommer inte behöva logga in på datorn, bildvisningen är redan öppen.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
