     "text": "Du är AT läkare och arbetar idag på akuten. Du ombeds undersöka en patient som inkommer på grund av hjärtrusningar och snabb puls.\nDin uppgift blir att:\nta anamnes och föreslå fortsatt utredning och behandling\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
