    "door": {
     "text": "På kirurgavdelningen ligger Monica, 77 år pga tilltagande buksmärtor sedan några dagar. Hon sökte redan i förrgår men skickades hem efter undersökning och datortomografi som visade lindrig divertikulit. Pga försämring i smärtorna och feber sökte hon på nytt imorse och lades in på akutvårdsavdelningen med dropp och i.v antibiotika. Hon är tidigare väsentligen frisk och aldrig opererad.\nNy datortomografi gjordes som visar en stråkighet kring sigmoideum, relativt mycket fri gas samt en del fri vätska. Flertal morfininjektioner har getts utan tillräcklig effekt, feber stigit till 38,9 grader och sköterskan tillkallar dig som jourhavande kirurg (underläkare). Hjärtlungstatus och blodtryck är utförd och behöver inte undersökas nu.\nDu ska:\n komplettera anamnes kortfattat med det du tycker är viktigast (figurant)\n undersöka buken (docka), berätta vad du gör och eventuella fynd\n förklara arbetsdiagnos för patienten och vidare handläggning.\nOm du överväger en operation så behöver du förklara hur den går till, vårdtid och eventuella komplikationsrisker\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
     "file": "OSCE II VT25 Dörrinformation.pdf",
     "page": 4
    },
