     "text": "Du är på ortopedmottagningen. Pat är 33 år med långvariga besvär i höger axel. Rtg höger axelled u.a.\nDin uppgift:\n Visa hur du undersöker axelledsrörlighet. Visa en test för att undersöka axelleden vid misstänkt instabilitet och en test för att undersöka axelleden vid impingement.\n Berätta högt vad du gör\n Patienten kan undersökas i stående och liggande!\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
