    "door": {
     "text": "Du är underläkare på en avdelning där det nyss kommit upp en 67-årig kvinna som opererat en knäprotes. Kvinnan har haft mycket ont- och har fått många olika smärtlindrande läkemedel på postoperativa avdelningen.\nAvdelningssköterskan kontaktar dig eftersom patienten inte längre är kontaktbar.\nA- Snarkande andning\nB- AF 7, saturation 88%\nC- HR 70, BT 140/60\nD- Ger ingen kontakt – grymtar vid smärtstimulering.\nDin uppgift är att: initiera adekvata åtgärder på patienten.\nDu har 6 minuter för att genomföra uppgiften.",
     "file": "Dörrinfo alla stationer om-OSCE II VT25.pdf",
     "page": 1
    },
