    "door": {
     "text": "Du är läkare på akutmottagningen.\nEn kvinna i 80-års åldern har ramlat på väg till bussen. Hon tog emot sig med utsträckt vänster arm. Nu har hon uttalad smärta i vänster handled och har svårt att röra den.\nDin uppgift:\n1. Utför ett kliniskt status av vänster handled (handledsstatus).\n2. Granska medföljande röntgenbilder och beskriv dina fynd.\n3. Formulera en trolig diagnos.\n4. Informera patienten och föreslå lämplig handläggning.\nDu har 6 minuter för att genomföra uppgiften.",
     "file": "Dörrinfo alla stationer om-OSCE II VT25.pdf",
     "page": 8
    },
    "rubric": null,
