     "text": "En 60-årig patient har opererats för tjocktarmscancer i sigmoideum. PAD visar ett radikalt borttaget adenocarcinom med kärl- och nervinväxt, och tumören har bevarad mismatch repair (pMMR). Tumören klassificeras som pT4N2M0 (Stadium IIIB).\nPatienten har nu kommit till onkologmottagningen för bedömning inför adjuvant cytostatika och sköterskan säger att patienten läst i journalen på 1177 om FOLFOX och undrar vad det är för sorts behandling\nDin uppgift är att:\n• Informera om syftet med behandlingen och prognosen av sjukdomen\n• Informera om hur den adjuvanta behandlingen går till praktiskt, inklusive förberedelser\n• Informera om vanliga biverkningar man kan drabbas av.\nDu har 6 minuter för att genomföra uppgiften.\nSprita händerna innan du går in.",
