     "text": "Du är underläkare på kirurgen och ska träffa Erik Eriksson 72 år som kommer på remiss från distriktsläkaren p.g.a. smärtor i en fot.\nFrågeställningen är ischemi.\nErik är gift, har 2 barn. Tidigare rökt men slutat. Han har opererat gallan.\nHar hypertoni som behandlas och har en tablettbehandlad diabetes mellitus.\nSista halvåret har han av och till haft ont i ena benet och foten. Han tycker han blir kall om foten.\nDu skall\n- göra ett ankelindex på denna patient\n- förklara för examinator hur du räknar ut ankelindex\n- förklara för patienten om det är normalt eller avvikande\nDu har 6 minuter för att genomföra uppgiften.",
