     "text": "Du är underläkare på Cancercentrum och har nu genomgång med sköterska inför helgen.\nPatienten i rum C9, som har en generaliserad cancer med avancerad skelett- och levermetastasering, har haft en snabb men förväntad försämring under dagen, patienten reagerar vid tilltal men ger ingen spontan kontakt. Hen har inte ätit idag och har med stor svårighet svalt sina tabletter. Hen är insulinbehandlad diabetiker.\nDin uppgift är att:\n1. Gå igenom patientens aktuella medicinering.\n2. Korrigera läkemedelslistan, ta bort det som du anser inte längre är nödvändigt samt sätt in läkemedel som du anser är nödvändiga för god vård.\n3. Ge övriga nödvändiga ordinationer inför kväll och natt\nUtför dina ändringar på den läkemedelslista som sköterskan presenterar för dig. För eventuell analgetika ska doser anges.\nDu har 6 minuter för att genomföra uppgiften.",
