     "text": "Du är akutläkare på sjukhusets akutmottagning. Patienten har stuckit sig i handen av misstag med en kniv. Såret har tejpats på vårdcentralen, men inga andra åtgärder har utförts.\nDu kan behöva komplettera anamnesen men det bedöms och poängsätts inte.\nDina uppgifter är nu att:\n1. Utföra ett för skadelokalisationen relevant och utförligt handstatus.\n2. Ange dina statusfynd högt för patienten så att hen förstår!\n3. Bedöma fynden och säga högt vilka strukturer som är skadade!\n4. Besluta om fortsatt handläggning i detta nu.\nDet du ser/hittar på patientens hand är vad du ska kunna se.\nDu har 6 minuter för att genomföra uppgiften.",
