     "text": "Du är underläkare på en vårdavdelning. En 64 årig patient lades in för snart 3 dygn sedan under preliminärdiagnos pyelonefrit.\nOdlingar har verifierat urinvägsinfektion som fokus med växt av Proteus mirabilis i blod och urin. Patienten behandlas sedan inläggning med\nCefotaxim.\nDu förbereder dig för att ronda patienten.\nDin uppgift är att vid ronden:\n• Ta riktad anamnes om aktuellt mående\n• Utvärdera behandlingseffekt\n• Föreslå vidare handläggning\n• Förmedla din bedömning till patienten\nPatientens labsvar och vitalparametrar finns inne på salen.\nDu får efterfråga symtom men ska INTE undersöka patienten.\nDu har 6 minuter för att genomföra uppgiften.",
