    "source": "Bedömningsmallar om-OSCE II VT26.pdf",
    "page": 11,
    "door": {
     "text": "Du är underläkare på infektionsavdelningen och ska ronda en 76 årig man med KAD som legat inne två dygn. Hen har feber nu på morgonen och ligger på en flersal med fyra sängar. Patientens journal är märkt med Typ I allergi mot penicillin.\nMorgonens prover (gårdagens provsvar inom parentes):\nCRP 120 (95) mg/L\nHb 96 (99) g/L\nLPK 14 (16,2) ×10⁹/L\nTPK 355 (330) ×10⁹/L\nKrea 130 (108 µmol/L\nNa 138 (137) mmol/L\nK 3,7 (3,4) mmol/L\nBlododling visar växt av Klebsiella pneumoniae i 2 av 4 blododlingsflaskor tagna på akuten\nResistensprofil:\nAmpicillin R\nPiperacillin/Tazobactam I\nCefotaxim R\nMeropenem S\nCiprofloxacin R\nGentamicin S\nTrimetoprim/Sulfa R\nTemp: 38,9 grader Celcius\nSat 94% O2 på rumsluft\nPatienten har producerat 1220 ml urin senaste dygnet\nPatienten står på Cefotaxim 1gx3 iv\nDin uppgift är att:\n1) Ta en riktad anamnes från patienten, du ska INTE utföra status.\n2) Värdera blododlingsresultaten och resistensbestämning\n3) Ta ställning till vidare handläggning och förklara dina beslut för patienten så att patienten förstår din handläggning (en icke medicinskt skolad person) med fokus på:\n- arbetsdiagnos\n- antimikrobiell behandling\nDu har 6 minuter för att genomföra uppgiften",
     "file": "T8 Dörrinfo alla stationer om-OSCE II VT26.pdf",
     "page": 14
    },
